excels.excel:

EXPORT WITH SHEET="库存量趋势", HEADER=true,
    MAPPING={"a":"月份","b":"期初","c":"入库","d":"出库","e":"期末"},
    FORMAT={"b":"#,##0","c":"#,##0","d":"#,##0","e":"#,##0"},
    FORMULAS={
        E2:'B2+C2-D2',E3:'E2+C3-D3',E4:'E3+C4-D4',E5:'E4+C5-D5',
        C6:'SUM(C2:C5)',D6:'SUM(D2:D5)',E6:'E5'
    },
    STYLE={ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}},
    GRAPH={TYPE=AREA3D, TITLE="库存量趋势图", CATEGORY_AXIS=月份, VALUE_AXIS=库存,
           CATEGORIES=["1月","2月","3月","4月"],
           SERIES=[
               {NAME=期末, DATA=[4800,5200,4600,5100]}
           ]}
